'use client';

import { useVehicle } from '@/app/axios';
import { useEffect, use } from 'react';
import { useTranslations } from 'next-intl';

const Page = ({ params }: { params: Promise<{ id: string }> }) => {
  const { id } = use(params);
  const { vehicle, fetchVehicleById, isLoading, error } = useVehicle();
  const t = useTranslations('vehicleDetails');

  useEffect(() => {
    if (id) {
      fetchVehicleById(id);
    }
  }, [fetchVehicleById, id]);

  if (isLoading) {
    return (
      <div className="flex h-[60vh] items-center justify-center">
        <div className="h-12 w-12 animate-spin rounded-full border-4 border-[#3B82F6] border-t-transparent shadow-sm"></div>
      </div>
    );
  }

  if (error || !vehicle) {
    return (
      <div className="global-container py-20 text-center">
        <h2 className="text-2xl font-bold text-gray-800">{t('notFound')}</h2>
        <p className="mt-2 text-gray-600">{error || t('checkId')}</p>
      </div>
    );
  }

  return (
    <main className="global-container py-8 md:py-12">
      <div className="grid grid-cols-1 gap-10 lg:grid-cols-2 lg:gap-16">
        {/* Left: Gallery (To be implemented) */}
        <div className="flex flex-col gap-6">
          <div className="bg-gray-100 p-10">Image Gallery Placeholder</div>
        </div>

        {/* Right: Info (To be implemented) */}
        <div className="flex flex-col gap-8">
          <div className="bg-gray-50 p-10">Vehicle Info Placeholder</div>
        </div>
      </div>
    </main>
  );
};

export default Page;
